import{_ as l,C as e,o as s,c as d,j as i,E as o,a as r,a2 as n}from"./chunks/framework.C21TwvGF.js";const p=JSON.parse(`{"title":"2-hafta (Mentor)","description":"","frontmatter":{"title":"2-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"11-sinf","link":"/mentor/11-sinf/"},"n":2,"bob":"I-bob · Dasturiy ta'minot ishlab chiqish asoslari","lessons":[{"g":4,"title":"Git branching strategiyalari va Conventional Commits","lead":"Bir vaqtning o'zida yuzlab muhandislar bitta loyihada bir-biriga xalaqit bermasdan qanday ishlaydi? Nega professional dasturchilar commit xabarlariga \\"ishladi\\" deb emas, qat'iy xalqaro standartda yozishadi? Ushbu darsda Git tarmoqlanish arxitekturasi va Conventional Commits madaniyatini o'rganamiz.","link":"/mentor/11-sinf/hafta-02/dars-1","slide":"/slaydlar/11-sinf/hafta-02/dars-1.html","test":"/slaydlar/11-sinf/hafta-02/dars-1-test.html"},{"g":5,"title":"Pull Request (PR) madaniyati, PR shabloni va Merge konfliktlar","lead":"Kod yozish — ishning bor-yo'g'i yarmi. Uni jamoaga to'g'ri taqdim etish, tushuntirish va xatolarsiz asosiy tarmoqqa birlashtirish haqiqiy muhandislik mahoratidir. Ushbu darsda professional Pull Request (PR) ochish, PR shablonlari, merge turlari va qo'rqinchli ko'ringan Merge Konfliktlarni oson hal qilishni o'rganamiz.","link":"/mentor/11-sinf/hafta-02/dars-2","slide":"/slaydlar/11-sinf/hafta-02/dars-2.html","test":"/slaydlar/11-sinf/hafta-02/dars-2-test.html"},{"g":6,"title":"Code Review metodologiyasi, etikasi va Branch Protection","lead":"Eng zo'r kod — bu bir kishi yozgan, lekin butun jamoaning aqli bilan sayqallangan koddir. Code Review nafaqat xatolarni ushlaydi, balki dasturchini tezroq o'stiradi. Ushbu darsda professional muloqot etikasi, \\"Nitpick vs Blocker\\", GitHub taklif kodi va asosiy tarmoqni qulflash (Branch Protection)ni o'rganamiz.","link":"/mentor/11-sinf/hafta-02/dars-3","slide":"/slaydlar/11-sinf/hafta-02/dars-3.html","test":"/slaydlar/11-sinf/hafta-02/dars-3-test.html"}],"test":"/slaydlar/11-sinf/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"mentor/11-sinf/hafta-02/index.md","filePath":"mentor/11-sinf/hafta-02/index.md"}`),h={name:"mentor/11-sinf/hafta-02/index.md"},g={class:"blk"},u={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},m={class:"blk"},c={id:"baholash-mezoni",tabindex:"-1"};function b(k,a,_,f,v,q){const t=e("Icon");return s(),d("div",null,[i("div",g,[i("h2",u,[o(t,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=n('<p>Har bir vazifa 20–30 daqiqa. Parol, shaxsiy token, maxfiy kalit va shaxsiy ma&#39;lumotlarni repozitoriyga yozmang: topshirishda faqat ochiq GitHub repo yoki Pull Request havolasi kerak.</p><h2 id="_4-dars-uchun-branching-va-conventional-commits" tabindex="-1">4-dars uchun (Branching va Conventional Commits) <a class="header-anchor" href="#_4-dars-uchun-branching-va-conventional-commits" aria-label="Permalink to &quot;4-dars uchun (Branching va Conventional Commits)&quot;">​</a></h2><p><strong>1-topshiriq: «GitHub Flow va Semantik commitlar»</strong></p><ol><li>O&#39;z portfolio repozitoriyangizda <code>feature/user-profile</code> nomli yangi tarmoq oching.</li><li>Kamida 3 ta mustaqil commit qiling. Commit xabarlari qat&#39;iy <strong>Conventional Commits</strong> spetsifikatsiyasi asosida bo&#39;lsin: <ul><li><code>feat(profile): add avatar upload and bio field</code></li><li><code>fix(profile): validate image file format and max size</code></li><li><code>docs(readme): document profile setup and requirements</code></li></ul></li><li>Terminalda <code>git log --oneline --graph</code> buyrug&#39;ini ishga tushiring va xabarlar aniq, semantik tartibda chiqqanini tekshiring.</li><li>Ushbu branch&#39;ni GitHub&#39;ga push qiling (<code>git push -u origin feature/user-profile</code>).</li></ol><p><strong>Kutiladigan natija:</strong> GitHub&#39;da yangi <code>feature/user-profile</code> tarmog&#39;i mavjud; commit xabarlari standart talablariga to&#39;liq javob beradi.<br><strong>Topshirish:</strong> GitHub tarmog&#39;i havolasi yoki commitlar tarixi skrinshoti.</p><hr><h2 id="_5-dars-uchun-pull-request-va-merge-konfliktlari" tabindex="-1">5-dars uchun (Pull Request va Merge Konfliktlari) <a class="header-anchor" href="#_5-dars-uchun-pull-request-va-merge-konfliktlari" aria-label="Permalink to &quot;5-dars uchun (Pull Request va Merge Konfliktlari)&quot;">​</a></h2><p><strong>2-topshiriq: «Mukammal PR va sun&#39;iy konfliktni yechish»</strong></p><ol><li><code>feature/user-profile</code> tarmog&#39;idan <code>main</code> tarmog&#39;iga qarab rasmiy Pull Request oching.</li><li>PR tavsifini <strong>What / Why / How</strong> professional shabloni bo&#39;yicha to&#39;ldiring: <ul><li><strong>What:</strong> Qanday o&#39;zgarishlar kiritildi?</li><li><strong>Why:</strong> Bu o&#39;zgarish nima uchun kerak (muammo yoki vazifa)?</li><li><strong>How:</strong> Texnik yechim qanday amalga oshirildi?</li><li>Skrinshot yoki test natijasi ilova qiling.</li></ul></li><li>Ataylab merge konflikti hosil qiling: <code>main</code> da ham, <code>feature/user-profile</code> da ham bitta faylning ayni bir qatorini o&#39;zgartirib commit qiling.</li><li>Konflikt belgilarini (<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>, <code>=======</code>, <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code>) o&#39;chirib, toza yechimni saqlang va commit qilib PR ni yangilang.</li></ol><p><strong>Kutiladigan natija:</strong> Tavsifi to&#39;liq, skrinshotli, nizosiz (Able to merge) yashil holatdagi Pull Request.<br><strong>Topshirish:</strong> GitHub Pull Request havolasi.</p><hr><h2 id="_6-dars-uchun-code-review-va-branch-protection" tabindex="-1">6-dars uchun (Code Review va Branch Protection) <a class="header-anchor" href="#_6-dars-uchun-code-review-va-branch-protection" aria-label="Permalink to &quot;6-dars uchun (Code Review va Branch Protection)&quot;">​</a></h2><p><strong>3-topshiriq: «Branch Protection va Taklif kodi»</strong></p><ol><li>Repozitoriyangiz sozlamalariga kiring (<code>Settings → Branches</code>) va <code>main</code> tarmog&#39;i uchun himoya qoidasini yoqing: <ul><li><code>Require a pull request before merging</code> (to&#39;g&#39;ridan-to&#39;g&#39;ri push taqiqlansin);</li><li><code>Require approvals: 1</code> (kamida 1 ta tasdiq talab qilinsin).</li></ul></li><li>Terminalda <code>main</code> tarmog&#39;ida turib to&#39;g&#39;ridan-to&#39;g&#39;ri push qilib ko&#39;ring va <code>GH006: Protected branch</code> xatoligini oling.</li><li>Do&#39;stingiz (yoki mentor) ochgan PR ga kiring: <ul><li>Kod diff&#39;idan bitta qatorni tanlab inline sharh qoldiring;</li><li>Kamida 1 ta <code>suggestion</code> bloki orqali to&#39;g&#39;rilangan kod taklifini taqdim eting;</li><li>Agar xatolik bo&#39;lmasa <code>Approve</code>, aks holda <code>Request changes</code> tugmasini bosing.</li></ul></li></ol><p><strong>Kutiladigan natija:</strong> <code>main</code> tarmog&#39;i himoyalangan, to&#39;g&#39;ridan-to&#39;g&#39;ri push bloklanadi; PR sahifasida konstruktiv inline sharh va bir bosishda qabul qilinuvchi code suggestion mavjud.<br><strong>Topshirish:</strong> Sozlangan Branch Protection sahifasi skrinshoti va yozilgan review/suggestion havolasi (yoki skrinshoti).</p><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><ul><li><strong>4-dars bo&#39;yicha tekshiruv:</strong> Commit xabarlari <code>type(scope): description</code> formatida ekanini, fe&#39;l hozirgi zamonda (masalan, <code>add</code> o&#39;rniga <code>added</code> emas) va kichik harflar bilan yozilganini tekshiring.</li><li><strong>5-dars bo&#39;yicha tekshiruv:</strong> O&#39;quvchi PR tavsifini bo&#39;sh qoldirmaganligini tekshiring. Konflikt yechilgandan so&#39;ng kodda Git qoldiqlari (<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD</code>, <code>=======</code>) qolib ketmaganiga ishonch hosil qiling.</li><li><strong>6-dars bo&#39;yicha tekshiruv:</strong> Branch Protection haqiqatan ishlashini o&#39;zingiz tekshiring (o&#39;quvchi repoga to&#39;g&#39;ridan-to&#39;g&#39;ri push qila olmasligi kerak). O&#39;quvchi yozgan sharh konstruktiv, hurmatli va shaxsiyatga tegmaydigan shaklda ekanini baholang.</li><li>Hafta yakunida o&#39;quvchining jamoaviy madaniyati va Git ko&#39;nikmalari o&#39;sish dinamikasini <code>baholash.md</code> jadvaliga kiriting.</li></ul>',18))]),i("div",m,[i("h2",c,[o(t,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=n('<p>Bitta o&#39;quvchi uchun shablon. Maqsad: haftalar bo&#39;yicha o&#39;sish dinamikasini kuzatish. Har hafta shu shablon nusxalanib, «Dinamika» jadvaliga bitta qator qo&#39;shiladi.</p><p><strong>O&#39;quvchi:</strong> ____________________ <strong>Guruh/sinf:</strong> 11-sinf <strong>Mentor:</strong> ____________________</p><h2 id="shkala-va-mezonlar-o-quv-dasturi-8-bo-lim" tabindex="-1">Shkala va mezonlar (o&#39;quv dasturi, 8-bo&#39;lim) <a class="header-anchor" href="#shkala-va-mezonlar-o-quv-dasturi-8-bo-lim" aria-label="Permalink to &quot;Shkala va mezonlar (o&#39;quv dasturi, 8-bo&#39;lim)&quot;">​</a></h2><p>100 ballik shkala: <strong>90–100 — 5 (a&#39;lo)</strong>, <strong>71–89 — 4 (yaxshi)</strong>, <strong>60–70 — 3 (qoniqarli)</strong>, <strong>0–59 — 2 (qoniqarsiz)</strong>.</p><p>Dasturdagi mezonlar: mavzu bo&#39;yicha tasavvurga ega bo&#39;lish; mavzu mohiyatini tushunish va aytib bera olish; bilimni amalda qo&#39;llash; ijodiy fikrlash va xulosa chiqarish; mustaqil ish bajarish.</p><table tabindex="0"><thead><tr><th>Mezon</th><th>Max</th></tr></thead><tbody><tr><td>Mohiyatni tushunadi va aytib bera oladi (tezkor nazorat, og&#39;zaki)</td><td>30</td></tr><tr><td>Amaliy topshiriq: to&#39;g&#39;ri va to&#39;liq, mustaqil bajarilgan</td><td>30</td></tr><tr><td>Ish sifati: toza kod/fayl, aniq commit xabarlari, tartibli tuzilma</td><td>20</td></tr><tr><td>Uyga vazifa bajarilgan va o&#39;z vaqtida topshirilgan</td><td>20</td></tr><tr><td><strong>Jami</strong></td><td><strong>100</strong></td></tr></tbody></table><hr><h2 id="_4-dars-branching-strategiyalari-va-conventional-commits" tabindex="-1">4-dars. Branching strategiyalari va Conventional Commits <a class="header-anchor" href="#_4-dars-branching-strategiyalari-va-conventional-commits" aria-label="Permalink to &quot;4-dars. Branching strategiyalari va Conventional Commits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>GitHub Flow afzalliklari; semantik prefikslar (<code>feat</code>, <code>fix</code>, <code>docs</code>, <code>refactor</code>); <code>git log --graph</code></td><td></td></tr><tr><td>Amaliyot /30</td><td>Feature branch ochish; o&#39;zgarishlarni kiritish; branch push qilish</td><td></td></tr><tr><td>Ish sifati /20</td><td>Commit xabarlari qat&#39;iy Conventional Commits formatida; atomik kichik commitlar</td><td></td></tr><tr><td>Uyga vazifa /20</td><td><code>feature/user-profile</code> tarmog&#39;i; 3 ta to&#39;g&#39;ri formatlangan commit</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><hr><h2 id="_5-dars-pull-request-va-merge-konfliktlarini-hal-qilish" tabindex="-1">5-dars. Pull Request va Merge Konfliktlarini hal qilish <a class="header-anchor" href="#_5-dars-pull-request-va-merge-konfliktlarini-hal-qilish" aria-label="Permalink to &quot;5-dars. Pull Request va Merge Konfliktlarini hal qilish&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>PR tavsifining 3 ta ustuni (What/Why/How); Merge vs Rebase vs Squash farqlari; konflikt sabablari</td><td></td></tr><tr><td>Amaliyot /30</td><td>GitHub&#39;da PR ochish; sun&#39;iy konflikt keltirib chiqarish va belgilarni tozalab yechish</td><td></td></tr><tr><td>Ish sifati /20</td><td>PR shabloni to&#39;liq to&#39;ldirilgan; skrinshot biriktirilgan; konflikt toza hal qilingan</td><td></td></tr><tr><td>Uyga vazifa /20</td><td>Mukammal PR havolasi; konflikt belgilari qolib ketmagan; yashil &quot;Able to merge&quot; holatida</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><hr><h2 id="_6-dars-code-review-metodologiyasi-va-branch-protection" tabindex="-1">6-dars. Code Review metodologiyasi va Branch Protection <a class="header-anchor" href="#_6-dars-code-review-metodologiyasi-va-branch-protection" aria-label="Permalink to &quot;6-dars. Code Review metodologiyasi va Branch Protection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>Review etikasi (&quot;shaxsni emas, kodni tahlil qilish&quot;); Blocker vs Nitpick; Branch Protection vazifasi</td><td></td></tr><tr><td>Amaliyot /30</td><td><code>Files changed</code> orqali inline sharh va <code>suggestion</code> bloki qoldirish; Branch protection sozlash</td><td></td></tr><tr><td>Ish sifati /20</td><td>Konstruktiv va xushmuomala sharhlar; <code>main</code> tarmog&#39;ining to&#39;g&#39;ri qulflanganligi</td><td></td></tr><tr><td>Uyga vazifa /20</td><td>Sozlangan Branch Protection skrinshoti; GitHub taklif kodi qabul qilingan PR</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><hr><h2 id="hafta-yakuni" tabindex="-1">Hafta yakuni <a class="header-anchor" href="#hafta-yakuni" aria-label="Permalink to &quot;Hafta yakuni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ko&#39;rsatkich</th><th>4-dars</th><th>5-dars</th><th>6-dars</th><th>O&#39;rtacha</th><th>Baho</th></tr></thead><tbody><tr><td>Ball</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Kuchli tomonlari:</strong> ____________________</p><p><strong>Rivojlantirish kerak:</strong> ____________________</p><p><strong>Mustaqillik darajasi</strong> (yordamsiz / ishora bilan / bosqichma-bosqich yordam): ____________________</p><hr><h2 id="dinamika-haftalar-bo-yicha" tabindex="-1">Dinamika (haftalar bo&#39;yicha) <a class="header-anchor" href="#dinamika-haftalar-bo-yicha" aria-label="Permalink to &quot;Dinamika (haftalar bo&#39;yicha)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hafta</th><th>Mavzu</th><th>O&#39;rtacha ball</th><th>Baho</th><th>O&#39;tgan haftaga nisbatan (↑ / = / ↓)</th><th>Asosiy kuzatuv</th></tr></thead><tbody><tr><td>1</td><td>IT ekotizimi, SDLC, Git, GitHub</td><td></td><td></td><td>boshlang&#39;ich nuqta</td><td></td></tr><tr><td>2</td><td>Branching, Pull Request, Konfliktlar, Code Review</td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td>Clean Code va SOLID tamoyillari</td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="hafta-xulosasi-va-3-haftaga-ko-prik" tabindex="-1">Hafta xulosasi va 3-haftaga ko&#39;prik <a class="header-anchor" href="#hafta-xulosasi-va-3-haftaga-ko-prik" aria-label="Permalink to &quot;Hafta xulosasi va 3-haftaga ko&#39;prik&quot;">​</a></h2><p><strong>Bu hafta:</strong> O&#39;quvchi individual kod yozish doirasidan chiqib, professional jamoaviy muhandislik madaniyatini o&#39;zlashtirdi: GitHub Flow, Conventional Commits, Pull Request arxitekturasi, merge konfliktlarini mustaqil yechish, konstruktiv Code Review va <code>main</code> tarmog&#39;ini himoyalash.</p><p><strong>Keyingi hafta (3-hafta, 7–9 darslar):</strong> Kod sifati va tizimli dasturlashning asosiy tamoyillari — <strong>Clean Code va SOLID</strong> (SRP, OCP, LSP, ISP, DIP). O&#39;quvchi ushbu tamoyillarni o&#39;zlashtirib, o&#39;zining kelajakdagi loyihalarini arxitekturaviy jihatdan mukammal va kengaytiriladigan darajada qurishni o&#39;rganadi.</p><p><strong>Mentor uchun keyingi dars oldidan tekshiruv:</strong></p><ul><li>O&#39;quvchi Git terminal buyruqlarida adashmayaptimi (ayniqsa, branchlararo o&#39;tish va rebase/merge)?</li><li>GitHub da PR ochish va sharh qoldirish erkin qo&#39;llanilayaptimi?</li><li>OOP (Obyektga yo&#39;naltirilgan dasturlash) asosiy tushunchalarini (klass, obyekt, vorislik, polimorfizm) eslaydimi? 3-hafta boshida OOP bo&#39;yicha 5 daqiqalik qisqa savol-javob o&#39;tkazish tavsiya etiladi.</li></ul>',33))])])}const z=l(h,[["render",b]]);export{p as __pageData,z as default};
